#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Hidden full-mark search for the public Pages shell.

The page auto-loads the explicitly authorized public marks index generated at
build time. Only marks are built in; reviews remain excluded. The browser mirrors
that index into IndexedDB for fast local searching and quote re-sampling.
"""

CSS = r'''
.hidden-evidence-search[hidden]{display:none!important}.hidden-evidence-search{position:fixed;inset:0;z-index:9998;background:rgba(0,0,0,.55);backdrop-filter:blur(8px);display:grid;place-items:start center;padding:7vh 18px 18px}.hes-panel{width:min(920px,100%);max-height:86vh;overflow:hidden;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:22px;box-shadow:0 24px 80px rgba(0,0,0,.28);display:flex;flex-direction:column}.hes-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:18px 20px;border-bottom:1px solid var(--line)}.hes-head h2{margin:0;font-size:18px}.hes-head p{margin:4px 0 0;color:var(--muted);font-size:11px}.hes-close{border:0;background:transparent;color:var(--muted);font-size:23px;cursor:pointer}.hes-tools{display:grid;grid-template-columns:1fr auto;gap:8px;padding:14px 20px;border-bottom:1px solid var(--line)}.hes-tools input[type=search],.hes-tools select{border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:12px;padding:10px 12px;font:inherit}.hes-meta{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:10px 20px;color:var(--muted);font-size:11px}.hes-results{overflow:auto;padding:4px 20px 20px;display:grid;gap:9px}.hes-result{border:1px solid var(--line);border-radius:14px;padding:12px 14px;background:var(--bg)}.hes-result .kind{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 7px;font-size:9px;color:var(--muted);margin-right:6px}.hes-result b{font-size:12px}.hes-result .meta{font-size:10px;color:var(--muted);margin-top:3px}.hes-result .text{font-family:ui-serif,"Songti SC","STSong",serif;font-size:14px;line-height:1.65;margin-top:8px;white-space:pre-wrap;word-break:break-word}.hes-result a{color:var(--accent);font-size:10px;text-decoration:none}.hes-empty{padding:30px 0;color:var(--muted);text-align:center;font-size:12px}@media(max-width:700px){.hidden-evidence-search{padding:2vh 8px 8px}.hes-panel{max-height:96vh}.hes-tools{grid-template-columns:1fr 105px}.hes-meta{align-items:flex-start}}
'''

HTML = r'''
<div class="hidden-evidence-search" id="hiddenEvidenceSearch" hidden aria-hidden="true">
  <section class="hes-panel" role="dialog" aria-modal="true" aria-labelledby="hesTitle">
    <header class="hes-head"><div><h2 id="hesTitle">划线快搜</h2><p>⌘/Ctrl + Shift + F · 6,099 条授权公开划线自动内置；搜索在当前浏览器本地执行。</p></div><button class="hes-close" id="hesClose" type="button" aria-label="关闭">×</button></header>
    <div class="hes-tools"><input id="hesQuery" type="search" autocomplete="off" placeholder="搜索划线 / 书名 / 作者 / 章节"><select id="hesKind"><option value="mark">全部划线</option></select></div>
    <div class="hes-meta"><span id="hesStatus">正在载入内置划线索引…</span></div>
    <div class="hes-results" id="hesResults"><div class="hes-empty">输入关键词开始搜索。</div></div>
  </section>
</div>
'''

JS = r'''
(()=>{function boot(){const overlay=document.getElementById('hiddenEvidenceSearch');if(!overlay||window.WeReadHiddenEvidenceSearch)return;const q=document.getElementById('hesQuery'),results=document.getElementById('hesResults'),status=document.getElementById('hesStatus');const DB='wereadPublicMarksV2',STORE='marks',META='meta';let cache=[];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const webSearch=title=>'https://weread.qq.com/web/search/books?keyword='+encodeURIComponent(String(title||'').trim());function normalize(x,i){const title=String(x.title||''),author=String(x.author||''),chapter=String(x.chapter||''),text=String(x.text||'').trim();return {id:String(x.id||`m:${x.bookId||''}:${i}`),kind:'mark',bookId:String(x.bookId||''),title,author,chapter,text,hay:(title+' '+author+' '+chapter+' '+text).toLowerCase()}}function openDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(STORE))db.createObjectStore(STORE,{keyPath:'id'});if(!db.objectStoreNames.contains(META))db.createObjectStore(META,{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}async function loadDb(){const db=await openDb();const tx=db.transaction([STORE,META],'readonly'),a=tx.objectStore(STORE).getAll(),m=tx.objectStore(META).get('stats');return await new Promise((resolve,reject)=>{tx.oncomplete=()=>resolve({items:a.result||[],stats:m.result?.value||null});tx.onerror=()=>reject(tx.error)})}async function saveDb(items){const db=await openDb();const tx=db.transaction([STORE,META],'readwrite'),s=tx.objectStore(STORE);s.clear();items.forEach(x=>s.put(x));tx.objectStore(META).put({key:'stats',value:{marks:items.length,total:items.length,source:'built-in-public-marks',indexedAt:new Date().toISOString()}});return await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}function updateStatus(){status.textContent=`已内置 ${cache.length.toLocaleString()} 条划线 · 搜索与重新抽样均在当前浏览器执行`}function render(){const needle=(q.value||'').trim().toLowerCase();if(!cache.length){results.innerHTML='<div class="hes-empty">划线索引仍在载入。</div>';return}if(!needle){results.innerHTML='<div class="hes-empty">输入关键词开始搜索。支持划线正文、书名、作者和章节。</div>';return}const found=[];for(const x of cache){if(x.hay.includes(needle)){found.push(x);if(found.length>=80)break}}if(!found.length){results.innerHTML='<div class="hes-empty">没有匹配结果。</div>';return}results.innerHTML=found.map(x=>`<article class="hes-result"><div><span class="kind">划线</span><b>《${esc(x.title||'未命名')}》</b></div><div class="meta">${esc(x.author||'')}${x.chapter?' · '+esc(x.chapter):''}</div><div class="text">${esc(x.text)}</div>${x.title?`<a href="${esc(webSearch(x.title))}" target="_blank" rel="noopener">在微信读书网页版查找 ↗</a>`:''}</article>`).join('')}function shortExcerpt(text,maxChars=90){const raw=String(text||'').replace(/\s+/g,' ').trim();if(raw.length<=maxChars)return {excerpt:raw,truncated:false};let out=raw.slice(0,maxChars),cut=Math.max(...['。','！','？','!','?','；',';'].map(p=>out.lastIndexOf(p)));if(cut>=Math.max(18,Math.floor(maxChars*.55)))out=out.slice(0,cut+1);return {excerpt:out.trimEnd()+'…',truncated:true}}async function ensureBuiltIn(){const built=(window.__WEREAD_BUILTIN_MARKS__||[]).map(normalize).filter(x=>x.text);if(built.length){cache=built;updateStatus();render();try{await saveDb(cache)}catch(_){/* IndexedDB is an optimization; in-memory search remains available. */}return}try{const data=await loadDb();cache=(data.items||[]).map(normalize).filter(x=>x.text);updateStatus();render()}catch(e){status.textContent='索引载入失败：'+e.message}}async function sampleMarks(limit=48,maxChars=90){if(!cache.length)await ensureBuiltIn();const pool=[...cache];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}const out=[],books=new Set();for(const x of pool){const key=x.bookId||x.title||x.id;if(books.has(key))continue;books.add(key);const ex=shortExcerpt(x.text,maxChars);out.push({bookId:x.bookId||'',title:x.title||'',author:x.author||'',chapter:x.chapter||'',excerpt:ex.excerpt,truncated:ex.truncated,sourceKind:'mark',webLink:webSearch(x.title||'')});if(out.length>=limit)break}return out}function open(){overlay.hidden=false;overlay.setAttribute('aria-hidden','false');ensureBuiltIn().then(()=>q.focus())}function close(){overlay.hidden=true;overlay.setAttribute('aria-hidden','true')}window.WeReadHiddenEvidenceSearch={open,close,sampleMarks,hydrate:ensureBuiltIn};document.getElementById('hesClose').onclick=close;overlay.addEventListener('click',e=>{if(e.target===overlay)close()});q.addEventListener('input',render);document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.shiftKey&&e.key.toLowerCase()==='f'){e.preventDefault();overlay.hidden?open():close();return}if(!overlay.hidden&&e.key==='Escape'){e.preventDefault();close()}});window.addEventListener('open-weread-private-search',open);ensureBuiltIn();if(new URLSearchParams(location.search).get('privateSearch')==='1')open()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot()})();
'''
